import{_ as o,o as t,c as s,af as a}from"./chunks/framework.Dt3O48XQ.js";const p=JSON.parse('{"title":"生命周期","description":"","frontmatter":{},"headers":[],"relativePath":"rooms/lifecycle.md","filePath":"rooms/lifecycle.md","lastUpdated":null}'),d={name:"rooms/lifecycle.md"};function n(i,e,r,c,l,h){return t(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="生命周期" tabindex="-1">生命周期 <a class="header-anchor" href="#生命周期" aria-label="Permalink to &quot;生命周期&quot;">​</a></h1><p>服务端 <strong><code>Room</code></strong> 从创建到销毁会经历一组固定回调；客户端则经历 <strong>连接 → 进房 → 收发 → 离房 / 断线重连</strong>。理解顺序有助于排查「消息还没注册就收到」「鉴权在错误阶段执行」等问题。</p><h2 id="服务端-room-回调-colyseus" tabindex="-1">服务端：Room 回调（Colyseus） <a class="header-anchor" href="#服务端-room-回调-colyseus" aria-label="Permalink to &quot;服务端：Room 回调（Colyseus）&quot;">​</a></h2><p>下列方法在 <strong><code>src/rooms/*.ts</code></strong> 各房间类中覆写（具体类名见 <a href="/xcs.github.io/guide/project-structure.html">项目结构</a>）。</p><table tabindex="0"><thead><tr><th>阶段</th><th>回调</th><th>典型职责</th></tr></thead><tbody><tr><td>房间创建</td><td><code>onCreate(options: Partial&lt;T&gt;)</code></td><td>初始化 <code>state</code>、<strong>注册 <code>onMessage</code></strong>、启动定时器；<code>options</code> 含创建房间时传入的 metadata</td></tr><tr><td>成员加入</td><td><code>onJoin(client, options)</code></td><td><strong>JWT / 业务校验</strong>（如 <code>@RequireAuth()</code>、<code>guildId</code>）、写入座位或在线列表；每个客户端进房都会触发一次</td></tr><tr><td>成员离开</td><td><code>onLeave(client, consented: boolean)</code></td><td>清理该 seat、广播离线；<code>consented === true</code> 多表示用户主动 <code>leave()</code>，<strong>false</strong> 多表示断线或异常关闭</td></tr><tr><td>房间销毁</td><td><code>onDispose()</code></td><td>停定时器、退订 Redis、释放外部资源</td></tr></tbody></table><h3 id="调用顺序-要点" tabindex="-1">调用顺序（要点） <a class="header-anchor" href="#调用顺序-要点" aria-label="Permalink to &quot;调用顺序（要点）&quot;">​</a></h3><ol><li><strong>首个</strong>客户端执行 <code>joinOrCreate(&quot;roomName&quot;, options)</code> 时，若尚无实例，服务端先 <strong><code>onCreate</code></strong>，再对该客户端 <strong><code>onJoin</code></strong>。</li><li>后续客户端 <strong><code>joinOrCreate</code> / <code>joinById</code></strong> 同一房间：不再执行 <code>onCreate</code>，只 <strong><code>onJoin</code></strong>。</li><li>若在 <code>onJoin</code> 中 <strong>抛错或拒绝连接</strong>，该客户端不会稳定留在房内，也不会触发正常的「加入成功」路径。</li><li>当 <strong><code>maxClients</code> 已满</strong> 或自定义逻辑拒绝时，应在文档与客户端提示「房间已满 / 拒绝原因」。</li></ol><p>本项目多数业务房在 <strong><code>onJoin</code></strong> 侧做 <strong>JWT</strong> 与 options 校验（见 <a href="/xcs.github.io/rooms/auth.html">鉴权与权限</a>）。</p><h3 id="消息注册时机" tabindex="-1">消息注册时机 <a class="header-anchor" href="#消息注册时机" aria-label="Permalink to &quot;消息注册时机&quot;">​</a></h3><p>务必在 <strong><code>onCreate</code></strong>（或至少在任意 <code>onJoin</code> 收到客户端消息前）完成 <strong><code>this.onMessage(...)</code></strong> 注册。否则早期到达的消息可能无人处理。延迟注册常见于错误重构，应避免。</p><h2 id="客户端-连接与房间" tabindex="-1">客户端：连接与房间 <a class="header-anchor" href="#客户端-连接与房间" aria-label="Permalink to &quot;客户端：连接与房间&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>说明</th></tr></thead><tbody><tr><td>建立传输层</td><td><code>Client</code> 指向 WebSocket 入口（与 HTTP 同源不同路径，见 Colyseus 文档）</td></tr><tr><td>进房</td><td><code>joinOrCreate(roomName, options)</code> 或 <code>joinById(roomId, options)</code>（匹配成功后常用）</td></tr><tr><td>进行中</td><td><code>send</code> / <code>onMessage</code>、可选监听 Schema <code>onChange</code></td></tr><tr><td>主动离开</td><td><code>room.leave()</code> → 服务端对该 client 走 <strong><code>onLeave(..., consented=true)</code></strong></td></tr><tr><td>异常断线</td><td>连接断开 → 服务端 <strong><code>onLeave(..., consented=false)</code></strong>；若在允许窗口内可用 <strong>重连</strong> 恢复同一逻辑玩家（<code>game_room</code> 见 <a href="/xcs.github.io/rooms/frame-sync-game-room.html">帧同步与游戏房</a>）</td></tr></tbody></table><p>客户端 <strong>options</strong> 必须与文档一致（如 <code>token</code>、<code>matchId</code>、<code>seatIndex</code>、<code>reconnectKey</code>），否则服务端校验失败。</p><h2 id="整体时序-示意" tabindex="-1">整体时序（示意） <a class="header-anchor" href="#整体时序-示意" aria-label="Permalink to &quot;整体时序（示意）&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  participant C as 客户端</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  participant R as Room 实例</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Note over R: 首个连接创建房间时</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  R-&gt;&gt;R: onCreate</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C-&gt;&gt;R: join / joinById</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  R-&gt;&gt;R: onJoin（鉴权、写入状态）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C-&gt;&gt;R: send / 状态由 Schema 推送</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Note over C,R: 业务进行中…</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C-&gt;&gt;R: leave 或断线</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  R-&gt;&gt;R: onLeave</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Note over R: 无人且满足销毁条件时</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  R-&gt;&gt;R: onDispose</span></span></code></pre></div><p>（具体是否立即 <code>onDispose</code> 与 <strong>是否允许空房常驻</strong>、<strong>是否手动 <code>disconnect()</code></strong> 等实现有关，以各 <code>Room</code> 源码为准。）</p><h2 id="与本项目几类房间的对应关系" tabindex="-1">与本项目几类房间的对应关系 <a class="header-anchor" href="#与本项目几类房间的对应关系" aria-label="Permalink to &quot;与本项目几类房间的对应关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>生命周期上的特点</th></tr></thead><tbody><tr><td><code>matchmaker_room</code></td><td>长时间驻留、大量客户端进出；<strong>不依赖单局 Schema</strong>，重在消息（<code>match:*</code>、<code>party:*</code>）与 Redis 队列</td></tr><tr><td><code>game_room</code></td><td>对局开始后人齐进入；结束时释放实例；关注 <strong>重连窗口</strong>、<code>playerOffline</code> / <code>reconnect:ok</code></td></tr><tr><td><code>chat_*</code></td><td>可按频道长期存在；世界频道注意 <strong>Redis</strong> 订阅生命周期（见 <a href="/xcs.github.io/rooms/messages.html">多模式聊天</a>）</td></tr><tr><td><code>loadtest_room</code></td><td>无鉴权，仅压测；生产务必关闭（见 <a href="/xcs.github.io/ops/load-testing.html">人数压力测</a>）</td></tr></tbody></table><h2 id="常见实践清单" tabindex="-1">常见实践清单 <a class="header-anchor" href="#常见实践清单" aria-label="Permalink to &quot;常见实践清单&quot;">​</a></h2><ul><li><strong><code>onCreate</code></strong>：创建 <code>state</code>、注册全部 <code>onMessage</code>、初始化 Redis / 定时器。</li><li><strong><code>onJoin</code></strong>：<code>RequireAuth</code>、校验 <code>guildId</code> / <code>teamId</code> / <code>matchId</code> 等与玩法相关的 options。</li><li><strong><code>onLeave</code></strong>：更新在线人数、广播 <code>playerLeft</code> 或聊天侧下线提示；区分主动离开与断线。</li><li><strong><code>onDispose</code></strong>：清理定时器、<code>clearInterval</code>、Redis <code>unsubscribe</code>、关闭自定义句柄。</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/xcs.github.io/rooms/overview.html">房间机制概览</a></li><li><a href="/xcs.github.io/rooms/auth.html">鉴权与权限</a></li><li><a href="/xcs.github.io/rooms/matchmaking.html">匹配与开房</a></li><li><a href="/xcs.github.io/rooms/frame-sync-game-room.html">帧同步与游戏房</a></li></ul>`,22)])])}const m=o(d,[["render",n]]);export{p as __pageData,m as default};
